begin;
insert into public.section_manuals(section_key,title,purpose,audience,quick_start,workflow,field_help,warnings,version,active)
values('production','Operations Manual — Production & Dispatch','Manage customer orders, actual quantities, delivery milestones and closure.',array['super_admin','corporate_manager','unit_supervisor','driver','operator','viewer']::public.app_role[],'Keep the programmed quantity as the baseline. Assign actual loads, complete delivery milestones, then close any order with a quantity difference.',jsonb_build_array('Select a planned trip or Additional delivery beyond the plan. Actual load quantity may be higher or lower than planned.','Adjust actual load quantity with a reason before departure. The original logistics plan remains in the history.','Use Close dispatch order after deliveries finish. Review programmed, dispatched, delivered and difference. Enter a reason when totals differ.','Peace River drivers and vehicles belong to Peace River Concrete Plant. Truck 131 is assigned to Olly.'),jsonb_build_object('Closure','At least one completed delivery is required. Ready and travelling loads block closure. Scheduled unproduced loads are cancelled when closing.','Permissions','Only authorized unit managers adjust quantities or close orders. Driver events and customer signatures remain separate.'),'Closing an order does not sign or accept a delivery for the customer.','0.3.12',true);
insert into public.section_manuals(section_key,title,purpose,audience,quick_start,workflow,field_help,warnings,version,active)
select section_key,title,purpose,audience,quick_start,
 workflow||jsonb_build_array(case when section_key='business_units' then 'Production & Dispatch: choose From and To dates, inclusive in Alberta time. Month to date is the initial range. Produced, dispatched, delivered, completed fleet services and hours follow activity dates. Pending and active counts show now.' else 'Deactivate validates reporting responsibilities before blocking access. Super Admins can Remove user after typing the exact name. Removal hides the account from the directory and retains history; reassign asset responsibilities and finish pending deliveries first.' end),field_help,warnings,'0.3.12',true
from public.section_manuals where active and section_key in ('business_units','admin');
update public.section_manuals set active=false,updated_at=now() where section_key in ('production','business_units','admin') and version<>'0.3.12' and active;
commit;
